  /**
   * Rerank Models Endpoint
   */
  rerank_models_endpoint: string | null;
  /**
   * Api Key Env
   */
  api_key_env: string | null;
  /**
   * Api Key
   */
  api_key: string | null;
  /**
   * Capabilities
   */
